-- Edit the existing publication task; approval and publication have distinct results.
UPDATE public.help_articles
SET body = replace(body,
  $old$<p>Saving page sections or header and footer changes keeps them in the Website Builder draft. Ask Mink to publish the page or header and footer when you are ready. Publication creates a separate review card for the whole saved draft, so check all its content before approving.</p>$old$,
  $new$<p>Saving page sections or header and footer changes keeps them in the Website Builder draft. The completed card says the change was saved to draft; that action does not make it live. After saving, the card checks the current draft and shows your next action. Choose <strong>Review publication</strong> to prepare a publication card in the same conversation. Review the whole saved draft, including other unpublished edits, then click its named <strong>Publish</strong> button to make that content live. Preparing a publication proposal costs 2 AI credits.</p><p>If publication is blocked, the card lists the current issues and any known valid link destinations. Choose <strong>Ask Mink to fix publishing issues</strong> to prepare corrections for review. A missing destination may need your choice; reviewing a correction does not publish legal pages or remove links automatically. Use <strong>Check publication status</strong> to refresh the card after other changes. When the saved content already matches the live store, the card says so.</p>$new$),
  updated_at = now()
WHERE slug = 'manage-your-website-with-mink-ai' AND status = 'published';
